/* ==================== الرواتب ==================== */
let salMonth=monthKey(today());
function renderPayroll(){const active=activeEmps().sort((a,b)=>(a.name||'').localeCompare(b.name||'','ar'));const rows=active.map(e=>({e,s:salaryDue(e,salMonth)})).filter(r=>r.s.state!=='na');const paid=rows.filter(r=>r.s.state==='paid'),unpaid=rows.filter(r=>r.s.state!=='paid');
  const totAED=rows.reduce((s,r)=>s+toAED(r.s.state==='paid'?+r.s.p.amount:netAfter(r.e),r.e.currency),0);const paidAED=paid.reduce((s,r)=>s+toAED(+r.s.p.amount,r.s.p.currency),0);
  const [y,m]=salMonth.split('-').map(Number);const prev=iso(new Date(y,m-2,1)).slice(0,7),next=iso(new Date(y,m,1)).slice(0,7);
  return `<div class="grid g4" style="margin-bottom:16px">
    <div class="tile"><div class="lbl">إجمالي رواتب الشهر</div><div class="num" style="font-size:1.4rem">${n0(totAED)} د.إ</div><div class="sub">≈ ${n0(totAED/S.settings.rate)} $</div></div>
    <div class="tile ok"><div class="lbl">تم صرفه</div><div class="num" style="font-size:1.4rem">${n0(paidAED)} د.إ</div><div class="sub">${paid.length} موظف</div></div>
    <div class="tile ${unpaid.length?'warn':'ok'}"><div class="lbl">متبقٍ</div><div class="num" style="font-size:1.4rem">${n0(Math.max(0,totAED-paidAED))} د.إ</div><div class="sub">${unpaid.length} موظف</div></div>
    <div class="tile"><div class="lbl">بالدولار</div><div class="num" style="font-size:1.4rem">${rows.filter(r=>r.e.currency==='USD').length}</div><div class="sub">موظف · سعر الصرف ${S.settings.rate}</div></div></div>
  <div class="card tight"><div class="card-head"><div class="toolbar"><button class="btn sm" onclick="salMonth='${prev}';render()">‹ السابق</button><h2 style="margin:0">${monthName(salMonth)}</h2><button class="btn sm" onclick="salMonth='${next}';render()">التالي ›</button>${salMonth!==monthKey(today())?`<button class="btn sm" onclick="salMonth='${monthKey(today())}';render()">الشهر الحالي</button>`:''}</div>
    <div class="toolbar"><button class="btn" onclick="exportCSV('payroll')">⬇️ كشف Excel</button><button class="btn" onclick="printPayroll()">🖨️ طباعة الكشف</button><button class="btn" onclick="exportWPS()">🏦 ملف تحويل بنكي</button>${unpaid.length?`<button class="btn ok" onclick="markAllPaid()">✅ تأكيد صرف الكل (${unpaid.length})</button>`:''}</div></div>
    <div class="table-wrap">${rows.length?`<table class="pay-table"><thead><tr><th>الموظف</th><th class="num">الأساسي</th><th class="num">البدلات</th><th class="num">الخصومات</th><th>سلف / مستحقات</th><th class="num">الصافي</th><th class="num">بالدرهم</th><th>الموعد</th><th>الحالة</th><th></th></tr></thead><tbody>${rows.map(({e,s})=>{const pos=empPosition(e);return `<tr><td><b data-go-emp="${e.id}" style="cursor:pointer">${esc(e.name)}</b><div class="muted mini">${esc(e.job||'')}</div></td><td class="num">${n2(e.basic)}</td><td class="num">${n2(e.allowances)}</td><td class="num">${n2(e.deductions)}${pos.loans.length&&s.state!=='paid'?`<div class="mini" style="color:var(--warn)">+ قسط ${n2(loanInstallments(e).reduce((a,x)=>a+x.amt,0))}</div>`:''}</td><td>${posBadge(e)}${pos.loans.length?`<div class="muted mini">متبقي سلف ${n2(pos.loanDue)} · ${pos.loans.map(a=>Math.ceil(advRemaining(a)/(+a.installment_amount||1))).reduce((x,y)=>Math.max(x,y),0)} قسط</div>`:''}</td><td class="num"><b>${s.state==='paid'?money(s.p.amount,s.p.currency):money(netAfter(e),e.currency)}</b>${s.state==='paid'&&(+s.p.bonus||0)?`<div class="mini muted">شامل مكافأة ${n2(s.p.bonus)}</div>`:''}${s.state!=='paid'?instNote(e):''}</td><td class="num muted">${n0(toAED(s.state==='paid'?+s.p.amount:netAfter(e),e.currency))}</td><td>${e.pay_day||25} ${monthName(salMonth).split(' ')[0]}</td><td>${s.state==='paid'?`<span class="badge b-ok">تم الصرف ${fmtDate(s.p.paid_at)}</span>`:s.state==='late'?`<span class="badge b-danger">متأخر ${s.days} يوم</span>`:s.state==='due'?'<span class="badge b-warn">مستحق</span>':`<span class="badge b-muted">بعد ${s.days} يوم</span>`}</td><td>${s.state==='paid'?`<button class="btn sm" onclick="printPayslip('${e.id}','${s.p.id}')">🧾</button> <button class="btn sm" onclick="deletePay('${s.p.id}')">تراجع</button>`:`<button class="btn sm ok" onclick="markPaid('${e.id}','${salMonth}')">✅ صرف</button>`} <button class="btn sm" onclick="openStatement('${e.id}')" title="كشف حساب">📄</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty">لا يوجد موظفون نشطون</div>'}</div></div>`;}
function loanInstallments(e){return S.advances.filter(a=>a.emp_id===e.id&&a.kind==='loan'&&a.status==='disbursed').map(a=>({a,amt:Math.min(advRemaining(a),+a.installment_amount||advRemaining(a))}));}
/* 5.7.0: الراتب بعد خصم أقساط السلف المجدولة لهذا الشهر — يُعرض في كل مكان (قائمة الموظفين، الملف، الرواتب، الكشوف) */
/* 5.7.1: العرض يشمل السلف المصروفة + المعتمدة (المجدولة) غير المصروفة بعد؛ الخصم الفعلي عند الصرف للمصروفة فقط */
const schedLoans=e=>S.advances.filter(a=>a.emp_id===e.id&&a.kind==='loan'&&(a.status==='approved'||a.status==='pending')&&+a.amount>0).map(a=>({a,amt:Math.min(+a.amount,+a.installment_amount||+a.amount)}));
const instSum=e=>loanInstallments(e).reduce((s,x)=>s+x.amt,0)+schedLoans(e).reduce((s,x)=>s+x.amt,0);
const netAfter=e=>Math.max(0,net(e)-instSum(e));
const instNote=(e,cls)=>{const i=instSum(e);return i>0?`<div class="mini ${cls||'muted'}" style="line-height:1.6">الراتب الكامل ${n2(net(e))} − قسط سلفة <b>${n2(i)}</b>${schedLoans(e).length?' (يشمل سلفة مجدولة لم تُصرف بعد)':''}</div>`:'';};
/* الأجر اليومي = الأساسي ÷ 30 · أيام الإجازة بدون راتب داخل شهر معيّن · قيمة الخصم */
const dailyWage=e=>(+e.basic||0)/30;
function unpaidLeaveDays(e,mk){const ms=mk+'-01';const [y,m]=mk.split('-').map(Number);const me=iso(new Date(y,m,0));let d=0;for(const l of S.leaves.filter(l=>l.emp_id===e.id&&l.type==='بدون راتب')){if(!l.start_date||!l.end_date)continue;const a=l.start_date>ms?l.start_date:ms;const b=l.end_date<me?l.end_date:me;if(b<a)continue;const span=daysBetween(l.start_date,l.end_date)+1;const ov=daysBetween(a,b)+1;d+=Math.round((+l.days||span)*ov/span*10)/10;}return Math.round(d*10)/10;}
function unpaidLeaveDeduction(e,mk){return +(unpaidLeaveDays(e,mk)*dailyWage(e)).toFixed(2);}
function payFormBody(e,mk){const inst=loanInstallments(e);const instSum=inst.reduce((s,x)=>s+x.amt,0);const umk=mk||monthKey(today());const ulDays=unpaidLeaveDays(e,umk);const ulDed=unpaidLeaveDeduction(e,umk);return `${inst.length?`<div class="banner warn" style="margin-bottom:12px"><span>🤝 يوجد ${inst.length} سلفة قائمة — سيُخصم قسط بقيمة <b>${n2(instSum)}</b> تلقائياً ويُسجَّل سداداً في الخزنة${inst.map(x=>`<div class="mini">• ${esc(x.a.reason||'')}: قسط ${n2(x.amt)} (متبقٍ ${n2(advRemaining(x.a))})</div>`).join('')}</span></div>`:''}${ulDays>0?`<div class="banner warn" style="margin-bottom:12px"><span>🏖️ إجازة بدون راتب هذا الشهر: <b>${ulDays}</b> يوم — سيُخصم <b>${n2(ulDed)}</b> تلقائياً (الأجر اليومي ${n2(dailyWage(e))} × ${ulDays}).</span></div>`:''}<input type="hidden" id="p_inst" value="${instSum}"><input type="hidden" id="p_uldays" value="${ulDays}"><input type="hidden" id="p_ulded" value="${ulDed}"><div class="frow4"><div class="field"><label>الأساسي</label><input type="number" step="0.01" id="p_basic" value="${e.basic||0}" dir="ltr" oninput="calcPay()"></div><div class="field"><label>البدلات</label><input type="number" step="0.01" id="p_allow" value="${e.allowances||0}" dir="ltr" oninput="calcPay()"></div><div class="field"><label>مكافأة / إضافي</label><input type="number" step="0.01" id="p_bonus" value="0" dir="ltr" oninput="calcPay()"></div><div class="field"><label>الخصومات (شامل أقساط السلف وأيام بدون راتب)</label><input type="number" step="0.01" id="p_ded" value="${(+e.deductions||0)+instSum+ulDed}" dir="ltr" oninput="calcPay()"></div></div>
  <div class="frow3"><div class="field"><label>الصافي</label><input type="number" step="0.01" id="p_amt" value="${(net(e)-instSum-ulDed).toFixed(2)}" dir="ltr"></div><div class="field"><label>العملة</label><select id="p_cur"><option value="AED" ${e.currency==='AED'?'selected':''}>AED</option><option value="USD" ${e.currency==='USD'?'selected':''}>USD</option></select></div><div class="field"><label>تاريخ الصرف</label><input type="date" id="p_date" value="${iso(today())}"></div></div><div class="frow"><div class="field"><label>طريقة الصرف</label><select id="p_method" onchange="payMethodChanged()"><option value="bank">🏦 تحويل بنكي / WPS</option><option value="cash">💵 نقداً من الخزينة</option><option value="cheque">🧾 شيك</option></select></div><div class="field"><label>يُخصم من حساب</label><select id="p_acct">${Object.keys(ACCOUNTS).map(k=>`<option value="${k}" ${k===((bankAccts()[0]||{}).key||'bank')?'selected':''}>${acctIcon(k)} ${esc(ACCOUNTS[k])}</option>`).join('')}</select></div></div><div id="p_chqbox" class="frow hidden"><div class="field"><label>رقم الشيك</label><input id="p_chqno" dir="ltr"></div><div class="field"><label>موعد الصرف</label><input type="date" id="p_chqdue"></div></div><div class="frow">${projField('p_proj',e.project_id||'','المشروع الذي يُحسب عليه الراتب')}<div class="field"><label>ملاحظة</label><input id="p_note" placeholder="مثال: خصم 2 يوم غياب / مكافأة أداء"></div></div>`;}
function calcPay(){$('#p_amt').value=(fn('p_basic')+fn('p_allow')+fn('p_bonus')-fn('p_ded')).toFixed(2);}
function markPaid(empId,mk){const e=empById(empId);openModal('تأكيد صرف راتب '+esc(e.name),`<p class="muted">${monthName(mk)}</p>${payFormBody(e,mk)}`,`<button class="btn primary" onclick="savePay('${empId}','${mk}')">تأكيد الصرف</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
function openPayForm(empId){const e=empById(empId);openModal('تسجيل دفعة راتب',`<div class="field"><label>الشهر</label><input type="month" id="p_month" value="${monthKey(today())}"></div>${payFormBody(e)}`,`<button class="btn primary" onclick="savePay('${empId}',null)">حفظ</button><button class="btn" onclick="closeModal()">إلغاء</button>`);}
function payMethodChanged(){const m=fv('p_method');const a=document.getElementById('p_acct');if(a){if(m==='cash')a.value='main';else{const b=(bankAccts()[0]||{}).key||'bank';if(ACCOUNTS[b])a.value=b;}}const box=document.getElementById('p_chqbox');if(box)box.classList.toggle('hidden',m!=='cheque');}
async function savePay(empId,mk){return withBusy(async()=>{mk=mk||fv('p_month');if(!mk){toast('اختر الشهر','err');return}if(S.payments.find(p=>p.emp_id===empId&&p.month===mk)){toast('يوجد دفعة مسجلة لهذا الشهر بالفعل','err');return}const e=empById(empId);const inst=loanInstallments(e);const method=fv('p_method')||'bank';const pid=uid();const paidAt=fv('p_date')||iso(today());if(method==='cash'&&!await requirePin('صرف راتب نقداً من الخزنة'))return;await DB.upsert('payments',{id:pid,emp_id:empId,month:mk,basic:fn('p_basic'),allowances:fn('p_allow'),bonus:fn('p_bonus'),deductions:fn('p_ded'),amount:fn('p_amt'),currency:fv('p_cur'),paid_at:paidAt,method,project_id:(document.getElementById('p_proj')?fv('p_proj'):(e.project_id||''))||null,note:fv('p_note')+(inst.length?` | قسط سلفة ${n2(inst.reduce((s,x)=>s+x.amt,0))}`:'')+(fn('p_uldays')>0?` | إجازة بدون راتب ${fn('p_uldays')} يوم: ${n2(fn('p_ulded'))}`:'')});let pacct=fv('p_acct')||(method==='cash'?'main':((bankAccts()[0]||{}).key||'bank'));if(method==='cash'&&isBankKey(pacct))pacct='main';if(method==='bank'&&!isBankKey(pacct))pacct=(bankAccts()[0]||{}).key||'bank';const pproj=(document.getElementById('p_proj')?fv('p_proj'):(e.project_id||''))||null;
if(method==='cheque')await DB.upsert('cheques',{id:uid(),kind:'out',number:fv('p_chqno'),party:e.name,bank:'',amount:fn('p_amt'),currency:fv('p_cur'),issue_date:paidAt,due_date:fv('p_chqdue')||null,account:isBankKey(pacct)?pacct:((bankAccts()[0]||{}).key||'bank'),note:`راتب ${monthName(mk)}`,emp_id:empId,project_id:pproj,ref_type:'payment',ref_id:pid});
else await DB.upsert('treasury',{id:uid(),date:paidAt,direction:'out',category:method==='cash'?'راتب نقدي':'راتب تحويل بنكي',amount:fn('p_amt'),currency:fv('p_cur'),emp_id:empId,account:pacct,ref_type:'payment',ref_id:pid,project_id:pproj,party:e.name,extra:JSON.stringify({'الطريقة':method==='cash'?'كاش':'تحويل بنكي'}),note:`راتب ${monthName(mk)}`,created_by:'admin'});for(const x of inst)await applyRepayment(x.a,x.amt,'خصم قسط من الراتب',mk,method==='cash');closeModal();toast('تم تسجيل الصرف'+(inst.length?' وخصم أقساط السلف':''),'ok');render();});}
async function markAllPaid(){const list=activeEmps().filter(e=>{const s=salaryDue(e,salMonth);return s.state!=='paid'&&s.state!=='na'});if(!await confirmBox(`تأكيد صرف رواتب ${list.length} موظف لشهر ${monthName(salMonth)} بالقيم المسجلة وبتاريخ اليوم؟`,'تأكيد الصرف'))return;for(const e of list){const inst=loanInstallments(e);const instSum=inst.reduce((s,x)=>s+x.amt,0);const ulDays=unpaidLeaveDays(e,salMonth);const ulDed=unpaidLeaveDeduction(e,salMonth);await DB.upsert('payments',{id:uid(),emp_id:e.id,month:salMonth,basic:+e.basic||0,allowances:+e.allowances||0,bonus:0,deductions:(+e.deductions||0)+instSum+ulDed,amount:net(e)-instSum-ulDed,currency:e.currency,paid_at:iso(today()),method:'bank',note:(inst.length?`قسط سلفة ${n2(instSum)}`:'')+(ulDays>0?`${inst.length?' | ':''}إجازة بدون راتب ${ulDays} يوم: ${n2(ulDed)}`:'')});for(const x of inst)await applyRepayment(x.a,x.amt,'خصم قسط من الراتب',salMonth,false);}toast(`تم تسجيل صرف ${list.length} راتب`,'ok');render();}
async function deletePay(id){if(!await confirmDel('حذف سجل هذه الدفعة؟ سيُلغى قيدها من الخزنة إن كانت نقدية، وتُعاد أقساط السلف المخصومة معها إلى رصيد السلفة.'))return;const pay=S.payments.find(x=>x.id===id);const t=S.treasury.find(x=>x.ref_type==='payment'&&x.ref_id===id);if(t)await DB.remove('treasury',t.id);const pc=S.cheques.find(c=>c.ref_type==='payment'&&c.ref_id===id);if(pc){if(pc.status==='cleared'){toast('شيك الراتب مصروف بالفعل — تراجع عن صرف الشيك أولاً من تبويب الشيكات','err');return}await DB.remove('cheques',pc.id);}if(pay){const inst=(pay.note||'').match(/قسط سلفة ([\d.,]+)/);if(inst){const total=+inst[1].replace(/,/g,'');const loans=S.advances.filter(a=>a.emp_id===pay.emp_id&&a.kind==='loan'&&['disbursed','settled'].includes(a.status));for(const a of loans){await DB.upsert('advances',{...a,remaining:Math.min(+a.amount,(+a.remaining||0)+Math.min(total,+a.installment_amount||total)),status:'disbursed'});}const reps=S.treasury.filter(x=>x.ref_type==='repayment'&&x.emp_id===pay.emp_id&&(x.note||'').includes('راتب '+monthName(pay.month)));for(const r of reps)await DB.remove('treasury',r.id);}}await DB.remove('payments',id);render();}
function printPayslip(empId,payId){const e=empById(empId);const p=payId?S.payments.find(x=>x.id===payId):null;const mk=p?p.month:monthKey(today());const b=p?+p.basic:+e.basic,a=p?+p.allowances:+e.allowances,bo=p?+p.bonus||0:0,d=p?+p.deductions:+e.deductions;const c=p?p.currency:e.currency;
  const html=letterShell(`<h2 style="text-align:center">كشف راتب — ${monthName(mk)}</h2>
  <table style="width:100%;margin:14px 0;border-collapse:collapse"><tr><td><b>الموظف</b></td><td>${esc(e.name)}</td><td><b>الرقم الوظيفي</b></td><td>${esc(e.code||'—')}</td></tr><tr><td><b>الوظيفة</b></td><td>${esc(e.job||'—')}</td><td><b>القسم</b></td><td>${esc(e.dept||'—')}</td></tr><tr><td><b>تاريخ التعيين</b></td><td>${fmtDate(e.hire_date)}</td><td><b>البنك / IBAN</b></td><td dir="ltr">${esc(e.bank||'')} ${esc(e.iban||'')}</td></tr></table>
  <table border="1" cellpadding="8" style="width:100%;border-collapse:collapse"><tr style="background:#eee"><th>البند</th><th>المبلغ (${c})</th></tr><tr><td>الراتب الأساسي</td><td>${n2(b)}</td></tr><tr><td>البدلات</td><td>${n2(a)}</td></tr>${bo?`<tr><td>مكافأة / إضافي</td><td>${n2(bo)}</td></tr>`:''}<tr><td><b>الإجمالي</b></td><td><b>${n2(b+a+bo)}</b></td></tr><tr><td>الخصومات</td><td>(${n2(d)})</td></tr><tr style="background:#f4f6fa"><td><b>صافي الراتب</b></td><td><b>${money(p?p.amount:net(e),c)}</b></td></tr></table>${(()=>{const u=(p&&p.note||'').match(/إجازة بدون راتب ([\d.]+) يوم: ([\d.,]+)/);if(u)return `<p class="mini">🏖️ تشمل الخصومات بدل أيام إجازة بدون راتب: <b>${u[1]}</b> يوم (${u[2]} ${c}).</p>`;if(!p&&unpaidLeaveDays(e,mk)>0)return `<p class="mini">🏖️ إجازة بدون راتب هذا الشهر: <b>${unpaidLeaveDays(e,mk)}</b> يوم — يُخصم ${n2(unpaidLeaveDeduction(e,mk))} ${c}.</p>`;return '';})()}${(()=>{const pos=empPosition(e);const inst=(p&&p.note||'').match(/قسط سلفة ([\d.,]+)/);return (inst||pos.loanDue)?`<p class="mini">${inst?`تشمل الخصومات قسط سلفة ${inst[1]}. `:''}${pos.loanDue?`المتبقي من السلف بعد هذا الشهر: <b>${n2(pos.loanDue)}</b> د.إ`:'تم سداد السلف بالكامل ✅'}</p>`:''})()}${p&&p.method==='cash'?'<p class="mini">طريقة الصرف: نقداً من الخزنة</p>':''}
  <p>${p?`تم الصرف بتاريخ ${fmtDate(p.paid_at)}${p.note?' — '+esc(p.note):''}`:'لم يُسجَّل الصرف بعد'}</p><div style="display:flex;justify-content:space-between;margin-top:60px"><div>توقيع الموظف: ____________________</div><div>توقيع المسؤول: ____________________</div></div>`);api.printHTML(html);}
function printPayroll(){const active=activeEmps().filter(e=>salaryDue(e,salMonth).state!=='na');api.printHTML(letterShell(`<h2>كشف رواتب ${monthName(salMonth)}</h2><table border="1" cellpadding="5" style="width:100%;border-collapse:collapse;font-size:12px"><tr style="background:#eee"><th>#</th><th>الموظف</th><th>الوظيفة</th><th>الأساسي</th><th>البدلات</th><th>الخصومات</th><th>قسط سلفة</th><th>الصافي بعد الخصم</th><th>العملة</th><th>الحالة</th><th>التوقيع</th></tr>${active.map((e,i)=>{const s=salaryDue(e,salMonth);return `<tr><td>${i+1}</td><td>${esc(e.name)}</td><td>${esc(e.job||'')}</td><td>${n2(e.basic)}</td><td>${n2(e.allowances)}</td><td>${n2(e.deductions)}</td><td>${s.p?'—':n2(instSum(e))}</td><td><b>${n2(s.p?s.p.amount:netAfter(e))}</b></td><td>${e.currency}</td><td>${s.state==='paid'?'تم الصرف '+fmtDate(s.p.paid_at):'لم يُصرف'}</td><td style="width:110px"></td></tr>`}).join('')}</table><p>الإجمالي بالدرهم (بعد خصم الأقساط): <b>${n2(active.reduce((s,e)=>{const d=salaryDue(e,salMonth);return s+toAED(d.p?+d.p.amount:netAfter(e),e.currency)},0))}</b></p>`,true));}
async function exportWPS(){const rows=activeEmps().map(e=>[e.code,e.name,e.name_en,e.bank,e.iban,e.currency,net(e).toFixed(2),toAED(net(e),e.currency).toFixed(2),salMonth]);const p=await api.exportCSV(`تحويل_رواتب_${salMonth}.csv`,csvOf(['الرقم الوظيفي','الاسم','Name','البنك','IBAN','العملة','الصافي','الصافي بالدرهم','الشهر'],rows));if(p)toast('تم حفظ ملف التحويل البنكي','ok');}

/* ==================== الإجازات ==================== */
let leaveYear=today().getFullYear();
function renderLeaves(){const active=activeEmps().sort((a,b)=>(a.name||'').localeCompare(b.name||'','ar'));const t=iso(today());const onLeave=active.filter(onLeaveToday);const upcoming=S.leaves.filter(l=>l.start_date>t&&daysUntil(l.start_date)<=30).sort((a,b)=>a.start_date.localeCompare(b.start_date));
  return `<div class="grid g3" style="margin-bottom:16px"><div class="tile info"><div class="lbl">في إجازة اليوم</div><div class="num">${onLeave.length}</div><div class="sub">${onLeave.slice(0,3).map(e=>esc(e.name)).join('، ')}</div></div><div class="tile"><div class="lbl">إجازات خلال 30 يوم</div><div class="num">${upcoming.length}</div><div class="sub">مجدولة</div></div><div class="tile warn"><div class="lbl">أرصدة متراكمة (${leaveYear})</div><div class="num">${n0(active.reduce((s,e)=>s+Math.max(0,leaveBalance(e,leaveYear).balance),0))}</div><div class="sub">يوم غير مستخدم — التزام مالي ≈ ${n0(active.reduce((s,e)=>s+toAED((+e.basic||0)/30*Math.max(0,leaveBalance(e,leaveYear).balance),e.currency),0))} د.إ</div></div></div>
  <div class="card tight"><div class="card-head"><div class="toolbar"><h2 style="margin:0">أرصدة الإجازات</h2><select class="search" style="min-width:100px" onchange="leaveYear=+this.value;render()">${[0,1,2].map(i=>{const y=today().getFullYear()-i;return `<option ${leaveYear===y?'selected':''}>${y}</option>`}).join('')}</select></div><div class="toolbar"><button class="btn" onclick="exportCSV('leaves')">⬇️ تصدير</button><button class="btn primary" onclick="openLeaveForm()">＋ تسجيل إجازة</button></div></div>
  <div class="table-wrap"><table><thead><tr><th>الموظف</th><th class="num">الاستحقاق السنوي</th><th class="num">المستحق حتى الآن</th><th class="num">المستخدم</th><th class="num">الرصيد</th><th class="num">مرضية</th><th>الحالة</th><th></th></tr></thead><tbody>${active.map(e=>{const lb=leaveBalance(e,leaveYear);const lv=onLeaveToday(e);return `<tr><td><b data-go-emp="${e.id}" style="cursor:pointer">${esc(e.name)}</b><div class="muted mini">${esc(e.dept||'')}</div></td><td class="num">${lb.entitlement}</td><td class="num">${lb.accrued}</td><td class="num">${lb.taken}</td><td class="num"><b class="${lb.balance<0?'':''}" style="color:${lb.balance<0?'var(--danger)':'inherit'}">${lb.balance}</b></td><td class="num">${lb.sick}</td><td>${lv?`<span class="badge b-info">في إجازة ${esc(lv.type)} حتى ${fmtDate(lv.end_date)}</span>`:'<span class="badge b-ok">على رأس العمل</span>'}</td><td><button class="btn sm" onclick="openLeaveForm('${e.id}')">＋ إجازة</button></td></tr>`}).join('')}</tbody></table></div></div>
  <div class="card"><h2>📅 الإجازات القادمة (30 يوم)</h2>${upcoming.length?upcoming.map(l=>{const e=empById(l.emp_id);return e?`<div class="list-alert" data-go-emp="${e.id}"><span><b>${esc(e.name)}</b> — ${esc(l.type)} من ${fmtDate(l.start_date)} إلى ${fmtDate(l.end_date)} (${l.days} يوم)</span><span class="badge b-muted">بعد ${daysUntil(l.start_date)} يوم</span></div>`:''}).join(''):'<div class="empty">لا توجد إجازات مجدولة</div>'}</div>`;}
function renderEmpLeaves(e,leaves,lb){return `<div class="kv" style="margin-bottom:14px"><div><small>الاستحقاق السنوي</small>${lb.entitlement} يوم</div><div><small>المستحق حتى اليوم</small>${lb.accrued}</div><div><small>المستخدم (سنوية)</small>${lb.taken}</div><div style="background:var(--primary-2)"><small>الرصيد المتاح</small><b>${lb.balance}</b> يوم</div><div><small>مرضية هذا العام</small>${lb.sick} <span class="mini muted">/ 90</span></div></div>
  <div class="toolbar" style="margin-bottom:12px"><button class="btn primary" onclick="openLeaveForm('${e.id}')">＋ تسجيل إجازة</button></div>${leaves.length?`<table><thead><tr><th>النوع</th><th>من</th><th>إلى</th><th class="num">الأيام</th><th>ملاحظة</th><th></th></tr></thead><tbody>${leaves.map(l=>`<tr><td><span class="badge ${l.type==='سنوية'?'b-primary':l.type==='مرضية'?'b-warn':l.type==='بدون راتب'?'b-danger':'b-muted'}">${esc(l.type)}</span></td><td>${fmtDate(l.start_date)}</td><td>${fmtDate(l.end_date)}</td><td class="num">${l.days}</td><td class="muted mini">${esc(l.note||'')}</td><td><button class="btn sm" onclick="openLeaveForm('${e.id}','${l.id}')">✏️</button> <button class="btn sm" onclick="openLetter('${e.id}','leave','${l.id}')">🖨️</button> <button class="btn sm danger" onclick="delLeave('${l.id}')">حذف</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">لا توجد إجازات مسجلة</div>'}`;}
function openLeaveForm(empId,leaveId){if(!S.employees.length){toast('أضف موظفاً أولاً','err');return}const L=leaveId?S.leaves.find(x=>x.id===leaveId):null;if(L)empId=L.emp_id;openModal(L?'تعديل إجازة':'تسجيل إجازة',`<div class="field"><label>الموظف</label><select id="l_emp">${activeEmps().map(e=>`<option value="${e.id}" ${e.id===empId?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div><div class="frow"><div class="field"><label>النوع</label>${selWithAdd('l_type','leaveTypes',L?L.type:'')}</div><div class="field"><label>عدد الأيام</label><input type="number" id="l_days" dir="ltr" step="0.5" value="${L?L.days:''}"></div></div><div class="frow"><div class="field"><label>من</label><input type="date" id="l_start" value="${L?L.start_date:iso(today())}" onchange="calcLeaveDays()"></div><div class="field"><label>إلى</label><input type="date" id="l_end" value="${L?L.end_date:iso(today())}" onchange="calcLeaveDays()"></div></div><div class="field"><label>ملاحظة</label><input id="l_note" value="${L?esc(L.note||''):''}"></div><p class="muted mini">💡 اختر النوع «بدون راتب» لو الإجازة مخصومة — هتُحسب تلقائياً (عدد الأيام × الأجر اليومي) وتُخصم من راتب نفس الشهر وتظهر في كشف الراتب. باقي الأنواع (سنوية/مرضية) مدفوعة بلا خصم.</p>`,`<button class="btn primary" onclick="saveLeave('${leaveId||''}')">حفظ</button><button class="btn" onclick="closeModal()">إلغاء</button>`);calcLeaveDays();}
function calcLeaveDays(){const a=fv('l_start'),b=fv('l_end');if(a&&b&&b>=a)$('#l_days').value=daysBetween(a,b)+1;}
async function saveLeave(leaveId){const emp_id=fv('l_emp'),start_date=fv('l_start'),end_date=fv('l_end');if(!start_date||!end_date||end_date<start_date){toast('تواريخ غير صحيحة','err');return}const days=+fv('l_days')||daysBetween(start_date,end_date)+1;if(!(days>0)){toast('عدد الأيام يجب أن يكون أكبر من صفر','err');if(window.shakeField)shakeField('l_days');return}const ov=S.leaves.find(l=>l.emp_id===emp_id&&l.id!==leaveId&&l.start_date<=end_date&&l.end_date>=start_date);if(ov){toast(`تتداخل مع إجازة ${ov.type} من ${fmtDate(ov.start_date)} إلى ${fmtDate(ov.end_date)}`,'err');return}await DB.upsert('leaves',{id:leaveId||uid(),emp_id,type:fv('l_type'),start_date,end_date,days,note:fv('l_note')});closeModal();toast(leaveId?'تم تعديل الإجازة':'تم تسجيل الإجازة','ok');render();}
async function delLeave(id){if(!await confirmDel('حذف هذه الإجازة؟'))return;await DB.remove('leaves',id);render();}

/* ==================== الخطابات ==================== */
const LETTERS={salary:'شهادة راتب (عربي/إنجليزي)',noc:'خطاب عدم ممانعة (NOC)',experience:'شهادة خبرة',warning:'إنذار كتابي',offer:'عرض عمل / عقد مبسط',clearance:'إخلاء طرف',eos:'تسوية نهاية الخدمة',leave:'إشعار موافقة إجازة',bank:'خطاب تعريف للبنك'};
function renderLetters(){return `<div class="card"><div class="card-head" style="padding:0 0 12px"><h2>🏗️ نماذج المقاولات والعملاء والجهات</h2><div class="toolbar"><button class="btn" onclick="go('guide')">📚 دليل الإجراءات</button><button class="btn" onclick="setTab='company';go('settings')">🏢 بيانات المنشأة والليتر هيد</button></div></div><p class="muted mini">تُطبع على ترويسة الشركة ببياناتها من الإعدادات. كل نموذج يطلب بيانات الجهة والمشروع ثم يفتح للتعديل الحر قبل الطباعة أو الحفظ PDF.</p><div class="grid g3">${Object.entries(COMPANY_LETTERS).map(([k,v])=>`<div class="card" style="margin:0;cursor:pointer" onclick="openCompanyLetter('${k}')"><b>${esc(v.t)}</b><div class="muted mini">${esc(v.d)}</div></div>`).join('')}</div></div><div class="card"><div class="card-head" style="padding:0 0 12px"><h2>📨 عروض العمل للمرشحين الجدد</h2><button class="btn primary" onclick="go('offers')">فتح قسم عروض العمل</button></div><p class="muted mini">عرض عمل عربي أو إنجليزي لمرشح لم يُضف بعد كموظف: الاسم، الجواز، الجنسية، الموبايل، الراتب والبدلات، التذكرة، التأمين، المواصلات، السكن، وأي مميزات — يُطبع على الليتر هيد، وعند القبول يتحول لملف موظف بضغطة.</p></div><div class="card"><h2>✉️ خطابات الموظفين</h2><p class="muted mini">اختر الموظف ونوع الخطاب، ثم عاينه وعدّله قبل الطباعة أو حفظه PDF. يُطبع بترويسة الشركة من الإعدادات.</p><div class="frow"><div class="field"><label>الموظف</label><select id="lt_emp">${S.employees.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>نوع الخطاب</label><select id="lt_kind">${Object.entries(LETTERS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div></div><button class="btn primary" onclick="openLetter(fv('lt_emp'),fv('lt_kind'))">معاينة الخطاب</button></div>
  <div class="grid g3">${Object.entries(LETTERS).map(([k,v])=>`<div class="card" style="cursor:pointer" onclick="$('#lt_kind').value='${k}';openLetter(fv('lt_emp'),'${k}')"><b>${v}</b><div class="muted mini">${({salary:'يثبت الراتب والوظيفة — للبنوك والسفارات',noc:'عدم ممانعة للسفر/رخصة القيادة/إقامة العائلة',experience:'تُمنح عند انتهاء الخدمة أو بالطلب',warning:'إنذار رسمي بحسب المادة 39 من قانون العمل',offer:'بنود العمل الأساسية للتوقيع',clearance:'إقرار بتسليم العهدة وعدم وجود مستحقات',eos:'تفصيل المكافأة والمستحقات النهائية',leave:'موافقة رسمية على الإجازة بالتواريخ',bank:'لفتح حساب بنكي أو تحويل راتب'})[k]}</div></div>`).join('')}</div>`;}
function renderLetterPicker(e){return `<div class="grid g3">${Object.entries(LETTERS).map(([k,v])=>`<button class="btn" style="justify-content:flex-start;padding:14px" onclick="openLetter('${e.id}','${k}')">${v}</button>`).join('')}</div>`;}
function letterShell(body,landscape,lang){const st=S.settings;const isEn=lang==='en';const img=(st.letterheadImg&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(st.letterheadImg))?st.letterheadImg:'';const mode=(!st.useLetterheadImg||!img||landscape)?'text':(st.letterheadMode||'full');const m=st.letterheadMargins||{top:38,bottom:74,side:16};
  const base=`body{font-family:"Segoe UI",Tahoma,Arial,sans-serif;color:#000;font-size:14px;line-height:1.9;margin:0}table td,table th{border:1px solid #999;padding:6px 10px}table{border-collapse:collapse}.ft{margin-top:40px;font-size:11px;color:#666;border-top:1px solid #ccc;padding-top:8px;text-align:center}.sig{display:flex;justify-content:space-between;margin-top:60px}h2,h3{page-break-after:avoid}tr{page-break-inside:avoid}.hd{display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #12B5A6;padding-bottom:10px;margin-bottom:22px}.hd h1{margin:0;font-size:20px;color:#0A8F84}.hd .en{direction:ltr;text-align:left;font-size:12px;color:#444}.hd img{max-height:70px}.lh img{width:100%;display:block;margin-bottom:14px}`;
  if(mode==='full'){const css=`@page{size:A4 portrait;margin:0}${base}html,body{width:210mm}.page{width:210mm;height:297mm;position:relative;overflow:hidden}.page+.page{page-break-before:always}.page .bg{position:absolute;inset:0;width:100%;height:100%;z-index:0}.page .area{position:absolute;top:${m.top}mm;left:${m.side}mm;right:${m.side}mm;bottom:${m.bottom}mm;overflow:hidden;z-index:1}#src{position:absolute;left:-9999px;top:0;width:${210-2*m.side}mm}`;
    const script=`window.paginate=function(){var src=document.getElementById('src'),pages=document.getElementById('pages');var area;function mk(){var p=document.createElement('div');p.className='page';p.innerHTML='<img class="bg" src="${img}"><div class="area"></div>';pages.appendChild(p);return p.querySelector('.area')}function fits(){return area.scrollHeight<=area.clientHeight+1}area=mk();var nodes=Array.prototype.slice.call(src.childNodes);for(var i=0;i<nodes.length;i++){var n=nodes[i];if(n.nodeType===1&&n.style&&n.style.pageBreakBefore==='always'){if(area.childNodes.length)area=mk();continue}area.appendChild(n);if(fits())continue;area.removeChild(n);if(n.tagName==='TABLE'&&n.rows.length>1){var rows=Array.prototype.slice.call(n.rows);var head=rows[0].querySelector('th')?rows.shift():null;var cur,tb;function newT(){cur=n.cloneNode(false);tb=document.createElement('tbody');if(head)tb.appendChild(head.cloneNode(true));cur.appendChild(tb);area.appendChild(cur)}newT();for(var r=0;r<rows.length;r++){tb.appendChild(rows[r]);if(!fits()){tb.removeChild(rows[r]);if(tb.rows.length===(head?1:0)){area.removeChild(cur)}area=mk();newT();tb.appendChild(rows[r])}}}else if(n.nodeType===1&&/^(DIV|OL|UL|SECTION)$/.test(n.tagName)&&n.children.length>1){var kids=Array.prototype.slice.call(n.childNodes);var wrap=n.cloneNode(false);area.appendChild(wrap);for(var k=0;k<kids.length;k++){wrap.appendChild(kids[k]);if(!fits()){wrap.removeChild(kids[k]);if(wrap.childNodes.length===0)area.removeChild(wrap);area=mk();wrap=n.cloneNode(false);area.appendChild(wrap);wrap.appendChild(kids[k]);}}}else{if(area.childNodes.length===0){area.appendChild(n);continue}area=mk();area.appendChild(n)}}src.parentNode.removeChild(src);return pages.children.length};`;
    return `<!DOCTYPE html><html dir="${isEn?'ltr':'rtl'}" lang="${isEn?'en':'ar'}"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'; script-src 'unsafe-inline'"><style>${css}</style></head><body><div id="pages"></div><div id="src">${body}</div><script>${script}<\/script></body></html>`;}
  const css=`@page{size:A4 ${landscape?'landscape':'portrait'};margin:${mode==='top'?'8mm 18mm 18mm':'18mm'}}${base}`;
  const logoTag=(st.logo&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(st.logo))?`<img src="${st.logo}">`:(window.DEFAULT_LOGO?`<img src="${window.DEFAULT_LOGO}">`:'');
  const header=mode==='top'?`<div class="lh"><img src="${img}"></div>`:isEn?`<div class="hd">${logoTag}<div style="direction:ltr;text-align:left;flex:1"><h1>${esc(st.company_en||st.company||'')}</h1><div class="mini">${esc(st.address||'')}${st.pobox?' · P.O. Box '+esc(st.pobox):''}${st.phone?' · '+esc(st.phone):''}${st.email?' · '+esc(st.email):''}${st.website?' · '+esc(st.website):''}</div><div class="mini">${st.license?'License No. '+esc(st.license):''}${st.trn?' · TRN '+esc(st.trn):''}</div></div><div>${esc(st.company||'')}</div></div>`:`<div class="hd"><div><h1>${esc(st.company||'')}</h1><div class="mini">${esc(st.address||'')}${st.pobox?' · ص.ب '+esc(st.pobox):''}${st.phone?' · '+esc(st.phone):''}${st.email?' · '+esc(st.email):''}${st.website?' · '+esc(st.website):''}</div><div class="mini">${st.license?'رخصة رقم '+esc(st.license):''}${st.trn?' · الرقم الضريبي '+esc(st.trn):''}</div></div>${logoTag}<div class="en">${esc(st.company_en||'')}</div></div>`;
  const ft=isEn?(st.letterFooter?esc(st.letterFooter):esc(st.company_en||st.company||'')+' — '+esc(st.address||'')+' — '+esc(st.phone||'')):(st.letterFooter?esc(st.letterFooter):esc(st.company||'')+' — '+esc(st.address||'')+' — '+esc(st.phone||''));
  return `<!DOCTYPE html><html dir="${isEn?'ltr':'rtl'}" lang="${isEn?'en':'ar'}"><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'"><style>${css}</style></head><body>${header}${body}<div class="ft">${ft}</div></body></html>`;}
function letterBody(e,kind,extraId,lang){const st=S.settings;const d=fmtDate(iso(today()));const isEn=lang==='en';const co=isEn?esc(st.company_en||st.company||''):esc(st.company||'');const nm=isEn?esc(e.name_en||e.name):esc(e.name);
  const sig=isEn?`<div class="sig"><div>${esc(st.signer||'Authorized Signatory')}<br>${esc(st.signerTitle||'')}<br><br>____________________<br>Stamp</div><div>Date: ${d}</div></div>`:`<div class="sig"><div>${esc(st.signer||'التوقيع')}<br>${esc(st.signerTitle||'')}<br><br>____________________<br>الختم</div><div>التاريخ: ${d}</div></div>`;
  const yrs=e.hire_date?(daysBetween(e.hire_date,iso(today()))/365).toFixed(1):'—';const total=(+e.basic||0)+(+e.allowances||0);
  switch(kind){
    case 'salary':
      if(isEn)return `<p>Date: ${d}</p><h2 style="text-align:center;text-decoration:underline">Salary Certificate</h2><p>To whom it may concern,</p><p>This is to certify that Mr./Ms. <b>${nm}</b>, ${esc(e.nationality||'')} national, has been employed with ${co} as <b>${esc(e.job||'')}</b> since ${fmtDate(e.hire_date)}, with a total monthly salary of <b>${e.currency} ${n2(total)}</b> (Basic ${n2(e.basic)} + Allowances ${n2(e.allowances)}), transferred to his/her account at ${esc(e.bank||'the bank')}.</p><p>This certificate is issued upon the employee's request without any liability on the company.</p>${sig}`;
      return `<p>التاريخ: ${d}</p><h2 style="text-align:center;text-decoration:underline">شهادة راتب</h2><p>إلى من يهمه الأمر،</p><p>تشهد ${co} بأن السيد/ة <b>${nm}</b>، ${esc(e.nationality||'')} الجنسية، يعمل لدينا بوظيفة <b>${esc(e.job||'')}</b> منذ تاريخ ${fmtDate(e.hire_date)}، ويتقاضى راتباً شهرياً إجمالياً قدره <b>${money(total,e.currency)}</b> (أساسي ${money(e.basic,e.currency)} + بدلات ${money(e.allowances,e.currency)})، يُحوَّل إلى حسابه لدى ${esc(e.bank||'البنك')}.</p><p>وقد أُعطيت هذه الشهادة بناءً على طلبه دون أدنى مسؤولية على الشركة تجاه الغير.</p>${sig}`;
    case 'noc':
      if(isEn)return `<p>Date: ${d}</p><h2 style="text-align:center;text-decoration:underline">No Objection Certificate</h2><p>To whom it may concern,</p><p>${co} has no objection to its employee Mr./Ms. <b>${nm}</b> (${esc(e.nationality||'')} national), employed as ${esc(e.job||'')} since ${fmtDate(e.hire_date)}, to <u>________________________________</u> (e.g. obtain a driving license / sponsor family / travel from ___ to ___).</p><p>This letter is issued upon the employee's request for submission to the relevant authorities.</p>${sig}`;
      return `<p>التاريخ: ${d}</p><h2 style="text-align:center;text-decoration:underline">خطاب عدم ممانعة</h2><p>إلى من يهمه الأمر،</p><p>لا تمانع ${co} في قيام موظفها السيد/ة <b>${nm}</b> (${esc(e.nationality||'')} الجنسية)، والذي يعمل لدينا بوظيفة ${esc(e.job||'')} منذ ${fmtDate(e.hire_date)}، بـ <u>________________________________</u> (مثال: استخراج رخصة قيادة / استقدام عائلته / السفر خلال الفترة من ___ إلى ___).</p><p>وقد أُعطي هذا الخطاب بناءً على طلبه لتقديمه إلى الجهة المختصة.</p>${sig}`;
    case 'experience':
      if(isEn)return `<p>Date: ${d}</p><h2 style="text-align:center;text-decoration:underline">Experience Certificate</h2><p>To whom it may concern,</p><p>This is to certify that Mr./Ms. <b>${nm}</b> was employed with ${co} as <b>${esc(e.job||'')}</b> in the ${esc(e.dept||'')} department from ${fmtDate(e.hire_date)} ${e.end_date||e.status==='inactive'?'to '+fmtDate(e.end_date||iso(today())):'to date'}, a total of ${yrs} years.</p><p>During the period of employment, he/she demonstrated competence, commitment, and exemplary conduct. We wish him/her all the best in future endeavors.</p>${sig}`;
      return `<p>التاريخ: ${d}</p><h2 style="text-align:center;text-decoration:underline">شهادة خبرة</h2><p>تشهد ${co} بأن السيد/ة <b>${nm}</b> قد عمل لدينا بوظيفة <b>${esc(e.job||'')}</b> في قسم ${esc(e.dept||'')} خلال الفترة من ${fmtDate(e.hire_date)} ${e.end_date||e.status==='inactive'?'إلى '+fmtDate(e.end_date||iso(today())):'وحتى تاريخه'}، أي ما يعادل ${yrs} سنة.</p><p>وقد أبدى خلال فترة عمله كفاءة والتزاماً وحسن سلوك، ونتمنى له التوفيق في مسيرته المهنية.</p>${sig}`;
    case 'warning':
      if(isEn)return `<p>Date: ${d}</p><h2 style="text-align:center;text-decoration:underline">Written Warning</h2><p>Employee: <b>${nm}</b> — Position: ${esc(e.job||'')} — Employee No.: ${esc(e.code||'')}</p><p>Please be advised that the following violation was recorded on ______:</p><p style="border:1px dashed #999;padding:20px;min-height:80px">______________________________________________________________</p><p>Accordingly, this written warning is issued to you pursuant to Article (39) of Federal Decree-Law No. 33 of 2021 concerning the Regulation of Labour Relations and its Executive Regulations. Should the violation recur, the company shall take the disciplinary measures prescribed by law.</p><p>Please acknowledge receipt by signing below.</p><div class="sig"><div>Employee Acknowledgment:<br><br>____________________</div><div>${esc(st.signer||'Management')}<br>${esc(st.signerTitle||'')}<br><br>____________________</div></div>`;
      return `<p>التاريخ: ${d}</p><h2 style="text-align:center;text-decoration:underline">إنذار كتابي</h2><p>السيد/ة: <b>${nm}</b> — الوظيفة: ${esc(e.job||'')} — الرقم الوظيفي: ${esc(e.code||'')}</p><p>نحيطكم علماً بأنه تم رصد المخالفة التالية بتاريخ ______:</p><p style="border:1px dashed #999;padding:20px;min-height:80px">______________________________________________________________</p><p>وعليه يُوجَّه إليكم هذا الإنذار الكتابي عملاً بأحكام المادة (39) من المرسوم بقانون اتحادي رقم 33 لسنة 2021 بشأن تنظيم علاقات العمل ولائحته التنفيذية، وفي حال تكرار المخالفة ستتخذ الشركة الإجراءات التأديبية المقررة قانوناً.</p><p>يُرجى التوقيع بالعلم.</p><div class="sig"><div>توقيع الموظف بالاستلام:<br><br>____________________</div><div>${esc(st.signer||'الإدارة')}<br>${esc(st.signerTitle||'')}<br><br>____________________</div></div>`;
    case 'offer':
      if(isEn)return `<p>Date: ${d}</p><h2 style="text-align:center;text-decoration:underline">Employment Offer</h2><p>Dear Mr./Ms. <b>${nm}</b>,</p><p>${co} is pleased to extend the following employment offer:</p><table style="width:100%;border-collapse:collapse"><tr><td>Position</td><td>${esc(e.job||'')}</td></tr><tr><td>Department</td><td>${esc(e.dept||'')}</td></tr><tr><td>Start Date</td><td>${fmtDate(e.hire_date)}</td></tr><tr><td>Basic Salary</td><td>${e.currency} ${n2(e.basic)}</td></tr><tr><td>Allowances</td><td>${e.currency} ${n2(e.allowances)}</td></tr><tr><td>Total Monthly Salary</td><td><b>${e.currency} ${n2(total)}</b></td></tr><tr><td>Annual Leave</td><td>${e.annual_leave||30} days paid</td></tr><tr><td>Contract Type</td><td>Fixed-term ${e.end_date?'ending '+fmtDate(e.end_date):'(two years, renewable)'}</td></tr><tr><td>Probation Period</td><td>6 months</td></tr></table><p>This employment relationship is governed by Federal Decree-Law No. 33 of 2021 and its Executive Regulations. An official employment contract shall be executed through the Ministry of Human Resources and Emiratisation (MOHRE).</p><div class="sig"><div>Employee Acceptance:<br><br>____________________</div><div>${esc(st.signer||'Management')}<br><br>____________________</div></div>`;
      return `<p>التاريخ: ${d}</p><h2 style="text-align:center;text-decoration:underline">عرض عمل</h2><p>السيد/ة <b>${nm}</b>،</p><p>يسر ${co} أن تقدم لكم عرض العمل التالي:</p><table style="width:100%;border-collapse:collapse"><tr><td>المسمى الوظيفي</td><td>${esc(e.job||'')}</td></tr><tr><td>القسم</td><td>${esc(e.dept||'')}</td></tr><tr><td>تاريخ المباشرة</td><td>${fmtDate(e.hire_date)}</td></tr><tr><td>الراتب الأساسي</td><td>${money(e.basic,e.currency)}</td></tr><tr><td>البدلات</td><td>${money(e.allowances,e.currency)}</td></tr><tr><td>إجمالي الراتب الشهري</td><td><b>${money(total,e.currency)}</b></td></tr><tr><td>الإجازة السنوية</td><td>${e.annual_leave||30} يوم مدفوعة الأجر</td></tr><tr><td>نوع العقد</td><td>محدد المدة ${e.end_date?'ينتهي '+fmtDate(e.end_date):'(سنتان قابلة للتجديد)'}</td></tr><tr><td>فترة التجربة</td><td>6 أشهر</td></tr></table><p>تخضع هذه العلاقة لأحكام المرسوم بقانون اتحادي رقم 33 لسنة 2021 ولائحته التنفيذية، وسيُحرَّر عقد العمل الرسمي عبر وزارة الموارد البشرية والتوطين.</p><div class="sig"><div>موافقة الموظف:<br><br>____________________</div><div>${esc(st.signer||'الإدارة')}<br><br>____________________</div></div>`;
    case 'clearance':
      if(isEn)return `<p>Date: ${d}</p><h2 style="text-align:center;text-decoration:underline">Clearance Certificate</h2><p>Employee: <b>${nm}</b> — Position: ${esc(e.job||'')} — Date of Joining: ${fmtDate(e.hire_date)} — Last Working Day: ${fmtDate(e.end_date||iso(today()))}</p><table style="width:100%;border-collapse:collapse"><tr style="background:#eee"><th>Item</th><th>Status</th><th>Authorized By</th></tr>${['Handover of assets (devices, keys, cards)','Settlement of advances & financial dues','Cancellation of work permit / residence visa','Handover of ongoing work','Health insurance card'].map(x=>`<tr><td>${x}</td><td>☐ Done</td><td></td></tr>`).join('')}</table><p>I, the undersigned, acknowledge that I have received all my entitlements and have no further claims against the company.</p><div class="sig"><div>Employee Signature:<br><br>____________________</div><div>${esc(st.signer||'Management')}<br>${esc(st.signerTitle||'')}<br><br>____________________</div></div>`;
      return `<p>التاريخ: ${d}</p><h2 style="text-align:center;text-decoration:underline">إخلاء طرف</h2><p>الموظف: <b>${nm}</b> — الوظيفة: ${esc(e.job||'')} — تاريخ التعيين: ${fmtDate(e.hire_date)} — تاريخ انتهاء الخدمة: ${fmtDate(e.end_date||iso(today()))}</p><table style="width:100%;border-collapse:collapse"><tr style="background:#eee"><th>البند</th><th>الحالة</th><th>توقيع المسؤول</th></tr>${['تسليم العهدة (أجهزة، مفاتيح، بطاقات)','تسوية السلف والمستحقات المالية','إلغاء بطاقة العمل / الإقامة','تسليم الأعمال الجارية','بطاقة التأمين الطبي'].map(x=>`<tr><td>${x}</td><td>☐ تم</td><td></td></tr>`).join('')}</table><p>أقر أنا الموقع أدناه بأنني استلمت كافة مستحقاتي ولا أطالب الشركة بأي حقوق أخرى.</p><div class="sig"><div>توقيع الموظف:<br><br>____________________</div><div>${esc(st.signer||'الإدارة')}<br>${esc(st.signerTitle||'')}<br><br>____________________</div></div>`;
    case 'eos':{const r=eosCalc(e,e.end_date||iso(today()));const lb=leaveBalance(e);const lc=(+e.basic||0)/30*Math.max(0,lb.balance);const mk=monthKey(today());const unpaidSal=S.payments.find(p=>p.emp_id===e.id&&p.month===mk)?0:net(e);
      if(isEn)return `<p>Date: ${d}</p><h2 style="text-align:center;text-decoration:underline">End of Service Settlement</h2><p>Employee: <b>${nm}</b> — Position: ${esc(e.job||'')} — From ${fmtDate(e.hire_date)} to ${fmtDate(e.end_date||iso(today()))} — Service: ${r?r.years.toFixed(2):'—'} years</p><table style="width:100%;border-collapse:collapse"><tr style="background:#eee"><th>Item</th><th>Details</th><th>Amount (${e.currency})</th></tr><tr><td>End of Service Gratuity</td><td>21 days × ${Math.min(r?r.years:0,5).toFixed(2)} yrs${r&&r.years>5?` + 30 days × ${(r.years-5).toFixed(2)} yrs`:''} × daily wage ${n2(r?r.daily:0)}</td><td>${n2(r&&r.eligible?r.gratuity:0)}</td></tr><tr><td>Unused Leave Balance</td><td>${lb.balance} days × ${n2((+e.basic||0)/30)}</td><td>${n2(lc)}</td></tr><tr><td>Last Month Salary (if unpaid)</td><td>${monthName(mk)}</td><td>${n2(unpaidSal)}</td></tr><tr><td>Deductions / Advances</td><td></td><td>( _______ )</td></tr><tr style="background:#f4f6fa"><td colspan="2"><b>Total Due</b></td><td><b>${n2((r&&r.eligible?r.gratuity:0)+lc+unpaidSal)}</b></td></tr></table><p class="mini">Calculated per Federal Decree-Law 33/2021. I acknowledge receipt of the above amount as full and final settlement of all my entitlements.</p><div class="sig"><div>Employee Signature:<br><br>____________________</div><div>${esc(st.signer||'Management')}<br>${esc(st.signerTitle||'')}<br><br>____________________</div></div>`;
      return `<p>التاريخ: ${d}</p><h2 style="text-align:center;text-decoration:underline">تسوية مستحقات نهاية الخدمة</h2><p>الموظف: <b>${nm}</b> — الوظيفة: ${esc(e.job||'')} — من ${fmtDate(e.hire_date)} إلى ${fmtDate(e.end_date||iso(today()))} — مدة الخدمة: ${r?r.years.toFixed(2):'—'} سنة</p><table style="width:100%;border-collapse:collapse"><tr style="background:#eee"><th>البند</th><th>التفاصيل</th><th>المبلغ (${e.currency})</th></tr><tr><td>مكافأة نهاية الخدمة</td><td>21 يوم × ${Math.min(r?r.years:0,5).toFixed(2)} سنة${r&&r.years>5?` + 30 يوم × ${(r.years-5).toFixed(2)} سنة`:''} × أجر يومي ${n2(r?r.daily:0)}</td><td>${n2(r&&r.eligible?r.gratuity:0)}</td></tr><tr><td>بدل إجازات غير مستخدمة</td><td>${lb.balance} يوم × ${n2((+e.basic||0)/30)}</td><td>${n2(lc)}</td></tr><tr><td>راتب الشهر الأخير (إن لم يُصرف)</td><td>${monthName(mk)}</td><td>${n2(unpaidSal)}</td></tr><tr><td>خصومات / سلف</td><td></td><td>( _______ )</td></tr><tr style="background:#f4f6fa"><td colspan="2"><b>الإجمالي المستحق</b></td><td><b>${n2((r&&r.eligible?r.gratuity:0)+lc+unpaidSal)}</b></td></tr></table><p class="mini">الحساب وفق المرسوم بقانون اتحادي 33/2021. أُقر باستلام المبلغ أعلاه تسوية نهائية لكافة مستحقاتي.</p><div class="sig"><div>توقيع الموظف:<br><br>____________________</div><div>${esc(st.signer||'الإدارة')}<br>${esc(st.signerTitle||'')}<br><br>____________________</div></div>`;}
    case 'leave':{const l=S.leaves.find(x=>x.id===extraId)||S.leaves.filter(x=>x.emp_id===e.id).sort((a,b)=>b.start_date.localeCompare(a.start_date))[0]||{type:'سنوية',start_date:iso(today()),end_date:iso(today()),days:1};
      if(isEn)return `<p>Date: ${d}</p><h2 style="text-align:center;text-decoration:underline">Leave Approval Notice</h2><p>Dear Mr./Ms. <b>${nm}</b> — ${esc(e.job||'')}</p><p>We are pleased to inform you that your <b>${esc(l.type)}</b> leave for <b>${l.days} day(s)</b> has been approved, effective from ${fmtDate(l.start_date)} to ${fmtDate(l.end_date)}. You are expected to resume duty on ${fmtDate(iso(new Date(parseD(l.end_date).getTime()+86400000)))}.</p><p>We wish you a pleasant leave.</p>${sig}`;
      return `<p>التاريخ: ${d}</p><h2 style="text-align:center;text-decoration:underline">إشعار الموافقة على إجازة</h2><p>السيد/ة <b>${nm}</b> — ${esc(e.job||'')}</p><p>نفيدكم بالموافقة على منحكم إجازة <b>${esc(l.type)}</b> لمدة <b>${l.days} يوم</b> اعتباراً من ${fmtDate(l.start_date)} وحتى ${fmtDate(l.end_date)}، على أن تباشروا العمل بتاريخ ${fmtDate(iso(new Date(parseD(l.end_date).getTime()+86400000)))}.</p><p>نتمنى لكم إجازة سعيدة.</p>${sig}`;}
    case 'bank':
      if(isEn)return `<p>Date: ${d}</p><p>To: ${esc(e.bank||'The Bank')}</p><h2 style="text-align:center;text-decoration:underline">Salary Transfer Letter</h2><p>Dear Sir/Madam,</p><p>This is to confirm that Mr./Ms. <b>${nm}</b>, ${esc(e.nationality||'')} national, is employed with ${co} as ${esc(e.job||'')} since ${fmtDate(e.hire_date)} under a ${e.end_date?'fixed-term':'current'} employment contract, with a total monthly salary of <b>${e.currency} ${n2(total)}</b>, transferred monthly through the Wage Protection System (WPS) to account <span dir="ltr">${esc(e.iban||'________________')}</span>.</p><p>This letter is issued upon the employee's request without any liability on the company.</p>${sig}`;
      return `<p>التاريخ: ${d}</p><p>السادة / ${esc(e.bank||'البنك')} المحترمين</p><h2 style="text-align:center;text-decoration:underline">خطاب تعريف بالراتب</h2><p>نفيدكم بأن السيد/ة <b>${nm}</b>، ${esc(e.nationality||'')} الجنسية، يعمل لدى ${co} بوظيفة ${esc(e.job||'')} منذ ${fmtDate(e.hire_date)} بموجب عقد عمل ${e.end_date?'محدد المدة':'ساري'}, وراتبه الشهري الإجمالي ${money(total,e.currency)}، ويُحوَّل راتبه شهرياً عبر نظام حماية الأجور (WPS) إلى حسابه رقم <span dir="ltr">${esc(e.iban||'________________')}</span>.</p><p>وقد أُعطي هذا الخطاب بناءً على طلبه دون أدنى مسؤولية على الشركة.</p>${sig}`;
  }return '';}
function openLetter(empId,kind,extraId){const e=empById(empId);if(!e){toast('اختر موظفاً','err');return}window._letterLang='ar';window._letterEmpId=empId;window._letterKind=kind;window._letterExtraId=extraId;const body=letterBody(e,kind,extraId,'ar');
  window._letterName=`${LETTERS[kind]}_${e.name}`;openModal(esc(LETTERS[kind]||'خطاب'),`<div class="toolbar" style="margin-bottom:8px;display:flex;gap:6px;align-items:center"><button class="btn sm" id="btnLangAr" onclick="switchLetterLang('ar')" style="font-weight:bold">عربي</button><button class="btn sm" id="btnLangEn" onclick="switchLetterLang('en')">English</button><span class="muted mini" style="margin-inline-start:8px">${tr('يمكنك التعديل مباشرة على النص قبل الطباعة.')}</span></div><div class="letter-preview" id="letterEdit" contenteditable="true">${body}</div>`,`<button class="btn primary" onclick="printLetter()">🖨️ ${tr('طباعة')}</button><button class="btn" onclick="saveLetterPDF()">📄 ${tr('حفظ PDF')}</button><button class="btn" onclick="closeModal()">${tr('إغلاق')}</button>`,true);}
function switchLetterLang(lang){window._letterLang=lang;const e=empById(window._letterEmpId);if(!e)return;const body=letterBody(e,window._letterKind,window._letterExtraId,lang);const el=$('#letterEdit');if(el)el.innerHTML=body;const ar=$('#btnLangAr'),en=$('#btnLangEn');if(ar)ar.style.fontWeight=lang==='ar'?'bold':'';if(en)en.style.fontWeight=lang==='en'?'bold':'';}
function cleanHTML(h){const t=document.createElement('div');t.innerHTML=h;t.querySelectorAll('script,iframe,object,embed,link,meta').forEach(n=>n.remove());t.querySelectorAll('*').forEach(el=>{[...el.attributes].forEach(a=>{if(/^on/i.test(a.name)||/javascript:/i.test(a.value))el.removeAttribute(a.name)})});return t.innerHTML;}
function printLetter(){api.printHTML(letterShell(cleanHTML($('#letterEdit').innerHTML),false,window._letterLang||'ar'));}
async function saveLetterPDF(){const p=await api.printPDF(letterShell(cleanHTML($('#letterEdit').innerHTML),false,window._letterLang||'ar'),(window._letterName||'letter').replace(/[\\/:*?"<>|]/g,'-')+'.pdf');if(p)toast('تم حفظ PDF: '+p,'ok');}

/* ==================== التقارير ==================== */
function renderReports(){const active=activeEmps();setTimeout(drawReportCharts,0);const eosRows=active.map(e=>({e,r:eosCalc(e),lb:leaveBalance(e)})).sort((a,b)=>(b.r?toAED(b.r.gratuity,b.e.currency):0)-(a.r?toAED(a.r.gratuity,a.e.currency):0));const eosTot=eosRows.reduce((s,x)=>s+(x.r?toAED(x.r.gratuity,x.e.currency):0),0);const lvTot=eosRows.reduce((s,x)=>s+toAED((+x.e.basic||0)/30*Math.max(0,x.lb.balance),x.e.currency),0);
  return `<div class="card"><h2>⬇️ تصدير Excel</h2><div class="toolbar">${[['employees','👤 الموظفون'],['documents','📄 المستندات'],['payroll','💵 كشف رواتب الشهر'],['payments','🧾 كل الدفعات'],['leaves','🏖️ أرصدة الإجازات'],['eos','🧮 التزامات نهاية الخدمة'],['alerts','🔔 التنبيهات']].map(([k,l])=>`<button class="btn" onclick="exportCSV('${k}')">${l}</button>`).join('')}<button class="btn" onclick="api.backup.exportPlain().then(p=>p&&toast('تم التصدير: '+p,'ok'))">🗂️ تصدير JSON كامل (غير مشفر)</button></div></div>
  <div class="grid g2"><div class="card"><h2>📊 تكلفة الرواتب — 12 شهر (د.إ)</h2><div class="chart-box" style="height:260px"><canvas id="rCost"></canvas></div></div><div class="card"><h2>🏢 كتلة الرواتب حسب القسم (د.إ/شهر)</h2><div class="chart-box" style="height:260px"><canvas id="rDept"></canvas></div></div>
  <div class="card"><h2>🌍 الجنسيات</h2><div class="chart-box" style="height:260px"><canvas id="rNat"></canvas></div></div><div class="card"><h2>📈 نمو عدد الموظفين</h2><div class="chart-box" style="height:260px"><canvas id="rHead"></canvas></div></div></div>
  <div class="card tight"><div class="card-head"><h2>🧮 الالتزامات المالية المتراكمة</h2><span class="muted mini">نهاية الخدمة ≈ <b>${n0(eosTot)}</b> د.إ · إجازات غير مستخدمة ≈ <b>${n0(lvTot)}</b> د.إ · الإجمالي ≈ <b>${n0(eosTot+lvTot)}</b> د.إ</span></div><div class="table-wrap"><table><thead><tr><th>الموظف</th><th>التعيين</th><th class="num">سنوات الخدمة</th><th class="num">الأساسي</th><th class="num">مكافأة نهاية الخدمة</th><th class="num">رصيد إجازة</th><th class="num">بدل الإجازة</th><th class="num">الإجمالي (د.إ)</th></tr></thead><tbody>${eosRows.map(({e,r,lb})=>`<tr><td><b data-go-emp="${e.id}" style="cursor:pointer">${esc(e.name)}</b></td><td>${fmtDate(e.hire_date)}</td><td class="num">${r?r.years.toFixed(1):'—'}</td><td class="num">${money(e.basic,e.currency)}</td><td class="num">${r&&r.eligible?money(r.gratuity,e.currency):'<span class="muted">—</span>'}</td><td class="num">${lb.balance}</td><td class="num">${money((+e.basic||0)/30*Math.max(0,lb.balance),e.currency)}</td><td class="num"><b>${n0(toAED((r&&r.eligible?r.gratuity:0)+(+e.basic||0)/30*Math.max(0,lb.balance),e.currency))}</b></td></tr>`).join('')}</tbody></table></div></div>`;}
function drawReportCharts(){const ms=monthsBack(12);mkChart('rCost',{type:'line',data:{labels:ms.map(k=>monthName(k).replace(/\s\d{4}/,'')),datasets:[{label:'مصروف فعلي',data:ms.map(k=>S.payments.filter(p=>p.month===k).reduce((s,p)=>s+toAED(+p.amount,p.currency),0)),borderColor:'#12B5A6',backgroundColor:'rgba(18,181,166,.15)',fill:true,tension:.3},{label:'الكتلة المتوقعة',data:ms.map(()=>activeEmps().reduce((s,e)=>s+toAED(net(e),e.currency),0)),borderColor:'#F2A93C',borderDash:[6,4],pointRadius:0}]},options:{responsive:true,maintainAspectRatio:false,scales:{y:{beginAtZero:true,ticks:{callback:v=>n0(v)}}}}});
  const dm={};activeEmps().forEach(e=>{const d=e.dept||'بدون قسم';dm[d]=(dm[d]||0)+toAED(net(e),e.currency)});const da=Object.entries(dm).sort((a,b)=>b[1]-a[1]);mkChart('rDept',{type:'bar',data:{labels:da.map(x=>x[0]),datasets:[{data:da.map(x=>Math.round(x[1])),backgroundColor:CHART_COLORS,borderRadius:6}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{ticks:{callback:v=>n0(v)}}}}});
  const nm={};activeEmps().forEach(e=>{const k=e.nationality||'غير محدد';nm[k]=(nm[k]||0)+1});const na=Object.entries(nm).sort((a,b)=>b[1]-a[1]);mkChart('rNat',{type:'doughnut',data:{labels:na.map(x=>x[0]),datasets:[{data:na.map(x=>x[1]),backgroundColor:CHART_COLORS,borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'60%',plugins:{legend:{position:'left',labels:{boxWidth:12}}}}});
  const hm=monthsBack(12);mkChart('rHead',{type:'line',data:{labels:hm.map(k=>monthName(k).replace(/\s\d{4}/,'')),datasets:[{label:'عدد الموظفين',data:hm.map(k=>{const end=k+'-31';return S.employees.filter(e=>e.hire_date&&e.hire_date<=end&&!(e.status==='inactive'&&e.end_date&&e.end_date<k+'-01')).length}),borderColor:'#5B5FE8',backgroundColor:'rgba(91,95,232,.15)',fill:true,tension:.3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{stepSize:1}}}}});}
async function exportCSV(kind){let head,rows,name;const emps=S.employees;
  if(kind==='employees'){head=['الرقم الوظيفي','الاسم','Name','الوظيفة','القسم','الجنسية','الهاتف','البريد','تاريخ الميلاد','تاريخ التعيين','انتهاء العقد','الحالة','العملة','الأساسي','البدلات','الخصومات','الصافي','يوم القبض','البنك','IBAN','ملاحظات'];rows=emps.map(e=>[e.code,e.name,e.name_en,e.job,e.dept,e.nationality,e.phone,e.email,e.birth_date,e.hire_date,e.end_date,e.status==='inactive'?'غير نشط':'نشط',e.currency,e.basic,e.allowances,e.deductions,net(e),e.pay_day,e.bank,e.iban,e.notes]);name='الموظفون';}
  else if(kind==='insurance'){head=['الموظف','المهنة','الجنسية','الحالة','رقم البطاقة','الانتهاء'];rows=activeEmps().map(e=>{const d=S.documents.filter(x=>x.emp_id===e.id&&x.type==='التأمين الطبي').sort((a,b)=>(b.expiry_date||'').localeCompare(a.expiry_date||''))[0];const du=d?daysUntil(d.expiry_date):null;return[e.name,e.trade||e.job,e.nationality,!d?'غير مضاف':du<0?'منتهٍ':du<=30?'ينتهي قريباً':'ساري',(d||{}).number||'',(d||{}).expiry_date||'']});name='التأمين_الصحي';}
  else if(kind==='documents'){head=['الموظف','نوع المستند','الرقم','تاريخ الإصدار','تاريخ الانتهاء','الأيام المتبقية','الحالة','ملاحظة'];rows=S.documents.map(d=>{const e=d.emp_id==='company'?{name:'المنشأة'}:(empById(d.emp_id)||{});const st=docStatus(d);return[e.name,d.type,d.number,d.issue_date,d.expiry_date,st.days,st.txt,d.note]});name='المستندات';}
  else if(kind==='payroll'){head=['الرقم الوظيفي','الموظف','الوظيفة','العملة','الأساسي','البدلات','الخصومات','قسط سلفة','الصافي بعد الخصم','الصافي بالدرهم','الحالة','تاريخ الصرف','المبلغ المصروف'];rows=activeEmps().map(e=>{const s=salaryDue(e,salMonth);return[e.code,e.name,e.job,e.currency,e.basic,e.allowances,e.deductions,instSum(e),netAfter(e),toAED(netAfter(e),e.currency).toFixed(2),s.state==='paid'?'تم الصرف':'لم يُصرف',s.p?s.p.paid_at:'',s.p?s.p.amount:'']});name='كشف_رواتب_'+salMonth;}
  else if(kind==='payments'){head=['الموظف','الشهر','الأساسي','البدلات','مكافأة','خصومات','الصافي','العملة','بالدرهم','تاريخ الصرف','ملاحظة'];rows=[...S.payments].sort((a,b)=>b.month.localeCompare(a.month)).map(p=>{const e=empById(p.emp_id)||{};return[e.name,p.month,p.basic,p.allowances,p.bonus,p.deductions,p.amount,p.currency,toAED(+p.amount,p.currency).toFixed(2),p.paid_at,p.note]});name='سجل_الدفعات';}
  else if(kind==='leaves'){head=['الموظف','الاستحقاق','المستحق حتى الآن','المستخدم','الرصيد','مرضية'];rows=activeEmps().map(e=>{const l=leaveBalance(e,leaveYear);return[e.name,l.entitlement,l.accrued,l.taken,l.balance,l.sick]});name='أرصدة_الإجازات_'+leaveYear;}
  else if(kind==='eos'){head=['الموظف','تاريخ التعيين','سنوات الخدمة','الأساسي','العملة','مكافأة نهاية الخدمة','بالدرهم'];rows=activeEmps().map(e=>{const r=eosCalc(e);return[e.name,e.hire_date,r?r.years.toFixed(2):'',e.basic,e.currency,r&&r.eligible?r.gratuity.toFixed(2):0,r&&r.eligible?toAED(r.gratuity,e.currency).toFixed(2):0]});name='نهاية_الخدمة';}
  else if(kind==='treasury'){head=['التاريخ','الاتجاه','التصنيف','الموظف','المبلغ','العملة','بالدرهم','البيان','مرجع'];rows=[...S.treasury].sort((a,b)=>a.date.localeCompare(b.date)).map(t=>[t.date,t.direction==='in'?'داخل':'خارج',t.category,(empById(t.emp_id)||{}).name||'',t.amount,t.currency,trAmt(t).toFixed(2),t.note,t.ref_type||'']);name='دفتر_الخزنة';}
  else if(kind==='advances'){head=['تاريخ الطلب','الموظف','النوع','المبلغ','العملة','السبب','الحالة','اعتمده','تاريخ الاعتماد','تاريخ الصرف','الأقساط','القسط','المتبقي','سند موقّع'];rows=S.advances.map(a=>[a.request_date,(empById(a.emp_id)||{}).name||'',a.kind==='custody'?'عهدة':'سلفة',a.amount,a.currency,a.reason,(ADV_ST[a.status]||{}).l||a.status,a.approved_by,a.approved_at,a.disbursed_at,a.installments,a.installment_amount,advRemaining(a),a.voucher_file_id?'نعم':'لا']);name='السلف_والعهد';}
  else if(kind==='expenses'){head=['التاريخ','من صرفه','التصنيف','البيان','المبلغ','العملة','مصدر الدفع','الحالة','فاتورة'];rows=[...S.expenses].sort((a,b)=>a.date.localeCompare(b.date)).map(x=>[x.date,(empById(x.emp_id)||{}).name||'الإدارة',x.category,x.description,x.amount,x.currency,x.custody_id?'عهدة':x.paid_from==='treasury'?'الخزنة':'الموظف',x.status,x.file_id?'نعم':'لا']);name='المصروفات';}
  else if(kind==='attendance'){head=['التاريخ','الموظف','التخصص','الحالة','الموقع','المهمة','العميل','خروج','عودة','ملاحظة'];rows=[...S.attendance].sort((a,b)=>b.date.localeCompare(a.date)).map(a=>{const e=empById(a.emp_id)||{};return[a.date,e.name,e.trade,(ATT[a.status]||{}).l||a.status,a.site,a.task,a.client,a.check_in,a.check_out,a.note]});name='سجل_الحضور';}
  else if(kind==='taxdocs'){head=['التاريخ','النوع','الجهة','TRN','الرقم','البيان','الصافي','نسبة','الضريبة','الإجمالي','محصّلة/مسددة','صورة'];rows=[...S.taxdocs].sort((a,b)=>a.date.localeCompare(b.date)).map(d=>[d.date,d.kind==='sale'?'مبيعات':'مشتريات',d.party,d.party_trn,d.number,d.description,d.net,d.vat_rate,d.vat,d.total,d.paid?'نعم':'لا',d.file_id?'نعم':'لا']);name='الفواتير_الضريبية';}
  else if(kind==='offers'){head=['التاريخ','المرشح','Name','الجواز','الجنسية','الموبايل','الوظيفة','العملة','الأساسي','سكن','مواصلات','أخرى','الإجمالي','تذكرة','تأمين','الحالة','صالح حتى'];rows=S.offers.map(o=>[(o.created_at||'').slice(0,10),o.name,o.name_en,o.passport,o.nationality,o.phone,o.job,o.currency,o.basic,o.housing,o.transport,o.other_allow,(+o.basic||0)+(+o.housing||0)+(+o.transport||0)+(+o.other_allow||0),o.ticket?'نعم':'لا',o.insurance?'نعم':'لا',(OFFER_ST[o.status]||{}).l||o.status,o.valid_until]);name='عروض_العمل';}
  else if(kind==='positions'){head=['الموظف','سلف عليه','عهدة مع الموظف','مصروفات له','رواتب متأخرة له','أشهر غير مصروفة','صافي الموقف'];rows=activeEmps().map(e=>{const p=empPosition(e);return[e.name,p.loanDue.toFixed(2),p.custDue.toFixed(2),p.reimbDue.toFixed(2),p.salaryDue.toFixed(2),p.unpaidMonths.join(' '),p.net.toFixed(2)]});name='مواقف_الموظفين';}
  else if(kind==='performance'){head=['الموظف','التخصص','الدرجة','إنجازات','مخالفات','غياب','أيام ميدان'];rows=activeEmps().map(e=>{const s=scorecard(e);return[e.name,e.trade||e.job,s.score,s.good,s.bad,s.absent,s.fieldDays]});name='الأداء';}
  else{head=['الأولوية','النوع','التفاصيل','الموظف'];rows=computeAlerts().map(a=>[a.lvl<=1?'عاجل':'متابعة',kindLabel(a.kind),a.txt,a.emp.name]);name='التنبيهات';}
  const p=await api.exportCSV(`${name}_${iso(today())}.csv`,csvOf(head,rows));if(p)toast('تم حفظ الملف: '+p,'ok');}

