function csvRows(text){text=text.replace(/^﻿/,'');const rows=[];for(const l of text.split(/\r?\n/)){if(!l.trim())continue;const out=[];let c='',q=false;for(const ch of l){if(ch==='"'){q=!q}else if((ch===','||ch===';')&&!q){out.push(c);c=''}else c+=ch}out.push(c);rows.push(out.map(s=>s.trim()))}return rows}
function importHeaderMap(headRow){
  const head=headRow.map(h=>String(h||'').trim().toLowerCase().replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي'));const used=new Set();
  const find=(exact,part)=>{let i=head.findIndex((h,k)=>!used.has(k)&&exact.includes(h));if(i<0)i=head.findIndex((h,k)=>!used.has(k)&&part.some(n=>h.includes(n)));if(i>=0)used.add(i);return i};
  const I={};
  I.visaExp=find(['انتهاء الاقامه','visa exp'],['انتهاء الاقام','visa exp']);
  I.passExp=find(['انتهاء الجواز','passport exp'],['انتهاء الجواز','passport exp']);
  I.visaNo=find(['رقم الاقامه','visa no'],['رقم الاقام','visa no']);
  I.passNo=find(['رقم الجواز','passport no'],['رقم الجواز','passport no']);
  I.code=find(['الرقم الوظيفي','رقم الوظيفي','code'],['رقم الوظيف','code']);
  I.name=find(['الاسم','name'],['اسم','name']);
  I.job=find(['الوظيفه','job','title'],['وظيف','job','title']);
  I.dept=find(['القسم','dept','department'],['قسم','dept','department']);
  I.nat=find(['الجنسيه','nationality'],['جنسي','nation']);
  I.phone=find(['الهاتف','phone'],['هاتف','جوال','phone']);
  I.cur=find(['العمله','currency'],['عمل','currency']);
  I.basic=find(['الاساسي','basic'],['اساس','basic']);
  I.allow=find(['البدلات','allow'],['بدل','allow']);
  I.ded=find(['الخصومات','deductions'],['خصم','خصوم','deduct']);
  I.pay=find(['يوم القبض','payday'],['يوم','payday']);
  I.hire=find(['تاريخ التعيين','hire date'],['تعيين','hire']);
  return I}
function importDate(v){v=String(v==null?'':v).trim();if(!v)return '';
  if(/^\d{5}(\.\d+)?$/.test(v)){const d=new Date(Date.UTC(1899,11,30)+Math.floor(+v)*86400000);return d.toISOString().slice(0,10)}
  let m=v.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);if(m)return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;
  m=v.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})/);if(m)return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;return ''}
function importNum(v){const n=parseFloat(String(v==null?'':v).replace(/[, ]/g,''));return isFinite(n)&&n>0?n:0}
async function importCSV(){
  let f;try{f=await api.file.pickSheet()}catch(e){toast('تعذّر فتح الملف','err');return}
  if(!f)return;let rows;
  try{rows=f.ext==='xlsx'?await xlsxRows(f.b64):csvRows(f.text)}catch(e){toast('الملف غير صالح أو تالف. استخدم قالب SEVEN','err');return}
  await importRows(rows)}
async function importRows(rows){
  if(rows.length<2){toast('الملف فارغ أو لا يحتوي صفوف بيانات','err');return}
  const I=importHeaderMap(rows[0]);if(I.name<0){toast('لم أجد عمود الاسم في الصف الأول','err');return}
  if(rows.length>5001){toast('الحد الأقصى 5000 موظف في الملف الواحد','err');return}
  const exist=new Set(S.employees.map(e=>String(e.code||'').trim()).filter(Boolean));const seen=new Set();
  let n=0,skipped=0,dup=0;
  for(const r of rows.slice(1)){const g=i=>i>=0?String(r[i]==null?'':r[i]).trim():'';
    if(!g(I.name))continue;const code=g(I.code);
    if(code&&(exist.has(code)||seen.has(code))){dup++;continue}
    const id=uid();const hire=importDate(g(I.hire))||iso(today());
    try{await DB.upsert('employees',{id,name:g(I.name).slice(0,200),code:code.slice(0,50),job:g(I.job).slice(0,120),dept:g(I.dept).slice(0,120),nationality:g(I.nat).slice(0,80),phone:g(I.phone).slice(0,40),currency:/usd|دولار|\$/i.test(g(I.cur))?'USD':'AED',basic:importNum(g(I.basic)),allowances:importNum(g(I.allow)),deductions:importNum(g(I.ded)),pay_day:Math.min(31,Math.max(1,Math.floor(+g(I.pay))||25)),hire_date:hire,status:'active',annual_leave:30});
      const ve=importDate(g(I.visaExp)),pe=importDate(g(I.passExp));
      if(ve)await DB.upsert('documents',{id:uid(),emp_id:id,type:'الإقامة',number:g(I.visaNo),expiry_date:ve});
      if(pe)await DB.upsert('documents',{id:uid(),emp_id:id,type:'جواز السفر',number:g(I.passNo),expiry_date:pe});
      if(code)seen.add(code);n++}catch(err){skipped++}}
  closeModal();toast(`تم استيراد ${n} موظف`+(dup?` · تم تخطي ${dup} مكرر (نفس الرقم الوظيفي)`:'')+(skipped?` · ${skipped} صف غير صالح`:''),'ok');go('employees')}


